const post = $input.item.json;
const niche = (post.NICHE || '').toLowerCase();

// Digital product catalog by niche
const catalog = {
  'veterinary': {
    name: 'Guía Veterinaria Completa',
    desc: 'Todo lo que necesitas saber para cuidar a tu mascota',
    url: 'https://hotmart.com/DIGITAL_VET_001'
  },
  'hurones': {
    name: 'Manual del Hurón Perfecto',
    desc: 'Guía completa de cuidados, salud y comportamiento',
    url: 'https://hotmart.com/DIGITAL_HUR_001'
  },
  'seguros': {
    name: 'Guía de Seguros para Latinoamérica',
    desc: 'Compara y elige el mejor seguro para tu familia',
    url: 'https://hotmart.com/DIGITAL_SEG_001'
  },
  'finanzas': {
    name: 'Finanzas Personales: De 0 a Libertad',
    desc: 'El sistema de ahorro e inversión que sí funciona',
    url: 'https://hotmart.com/DIGITAL_FIN_001'
  },
  'insurance': {
    name: "Insurance Buyer's Complete Guide",
    desc: 'Everything you need to know before buying any insurance',
    url: 'https://hotmart.com/DIGITAL_INS_001'
  },
  'legal-us': {
    name: 'Know Your Rights: US Legal Guide',
    desc: 'Protect yourself with essential legal knowledge',
    url: 'https://hotmart.com/DIGITAL_LEG_001'
  }
};

const product = catalog[niche] || {
  name: 'Guía Premium del Tema',
  desc: 'Contenido exclusivo y profundo para dominar el tema',
  url: 'https://hotmart.com/DIGITAL_GEN_001'
};

const ctaHtml = `<div class="digital-product-cta" style="background: linear-gradient(135deg, #667eea 0%, #764ba2 100%); border-radius: 12px; padding: 24px; margin: 30px 0; color: white; text-align: center;">
  <h3 style="margin: 0 0 12px; font-size: 1.4em; color: white;">📚 Guía Digital: ${product.name}</h3>
  <p style="margin: 0 0 16px; opacity: 0.9; font-size: 0.95em;">${product.desc}</p>
  <a href="${product.url}" target="_blank" rel="nofollow" style="display: inline-block; background: white; color: #667eea; padding: 12px 28px; border-radius: 8px; text-decoration: none; font-weight: bold; font-size: 1em;">Obtener Guía →</a>
</div>`;

let html = post.HTML_CONTENT || '';

// Try to insert before </article>, otherwise append
if (html.includes('</article>')) {
  html = html.replace('</article>', ctaHtml + '</article>');
} else {
  html = html + ctaHtml;
}

return {
  json: {
    ROW_NUMBER: post.ROW_NUMBER,
    POST_ID: post.POST_ID,
    BLOG_ID: post.BLOG_ID,
    TITLE: post.TITLE,
    HTML_CONTENT_UPDATED: html
  }
};
